import { commonSettings } from "@episerver/shared/common-settings";

import { AuthState } from "./internal/modules/auth";
import { BaseState } from "./internal/modules/base.state";
import { StateManager } from "./internal/state";

function init(target: Window & typeof globalThis): void {
    // The actual manager is initialized in memory,
    const manager = new StateManager();

    target.state = {
        get: (name: string) => manager.states[name],
        getAll: () => manager.states,
        register: <T>(state: BaseState<T>) => {
            manager.register(state);
        },
    };

    // Since AuthState is technically not related to the CMS, we can register it here.
    manager.register(new AuthState(commonSettings));
}

init(window);
