export abstract class BaseState<T> {
    protected subscribers: Set<(state: T) => void> = new Set();

    abstract get(): T;

    abstract name: string;

    constructor() {}

    public subscribe(callback: (state: T) => void): () => void {
        this.subscribers.add(callback);

        // Immediately notify the subscriber with the current state,
        // because they might be subscribing after the state has already changed.
        callback(this.get());

        // Return an unsubscribe function
        return () => this.subscribers.delete(callback);
    }

    public refresh(): void {
        // no-op, can be overriden by subclasses
    }

    protected notify(state?: T): void {
        if (state) {
            this.subscribers.forEach((callback) => callback(state));
        } else {
            this.subscribers.forEach((callback) => callback(this.get()));
        }
    }
}
