import { IStateFacade, IStateManagerFacade } from "./models";
import { BaseState } from "./modules/base.state";

export class StateManager {
    private _states: Map<string, BaseState<any>> = new Map();
    private _stateCache: Map<string, IStateFacade<any>> = new Map();

    constructor() {}

    public register<T>(state: BaseState<T>): void {
        if (this._states.has(state.name)) {
            return;
        }

        // Register a state object
        this._states.set(state.name, state);
    }

    public get states() {
        const result = {} as IStateManagerFacade;

        for (const [name, state] of this._states) {
            // Lazy create facade objects
            if (!this._stateCache.has(name)) {
                this._stateCache.set(name, {
                    get: () => state.get(),
                    subscribe: (callback) => state.subscribe(callback),
                    refresh: () => state.refresh(),
                });
            }
            result[name] = this._stateCache.get(name)!;
        }

        return result;
    }
}
