import { CommonSettings } from "@episerver/shared/autogenerated-types/CommonSettings";

import { BaseState } from "../base.state";

export interface IAuthState {
    token?: string;
    expiry?: Date;
}
export class AuthState extends BaseState<IAuthState> {
    private timeout?: NodeJS.Timeout;

    private token?: string;
    private expiry?: Date;

    constructor(private settings?: CommonSettings) {
        super();
        this.scheduleTokenRefresh();
    }

    public name: string = "authState";

    // Public API for reading the state
    public get() {
        return { token: this.token };
    }

    // Internal API
    private async scheduleTokenRefresh(): Promise<void> {
        try {
            const { token, expiry } = await this.getToken();
            this.set(token, expiry);

            if (!this.token || !this.expiry) {
                return;
            }

            // Clear any existing timeout to prevent multiple timers running
            if (this.timeout) {
                clearTimeout(this.timeout);
            }

            // Set up a timer to refresh the token before it expires
            const timer = this.expiry.getTime() - Date.now() - 30_000; // 30 seconds before expiry
            if (timer > 0) {
                this.timeout = setTimeout(() => this.scheduleTokenRefresh(), timer);
            } else {
                // If the token is already expired or about to expire, fetch a new one immediately
                this.scheduleTokenRefresh();
            }
        } catch (error) {
            setTimeout(() => this.scheduleTokenRefresh(), 30_000);
        }
    }

    private async getToken(): Promise<{ token: string; expiry: Date }> {
        const url = this.settings?.shellModuleUrl;

        if (!url) {
            throw new Error("Shell module URL is not configured.");
        }

        const response = await fetch(`${url}auth/token`);
        if (!response.ok) {
            throw new Error("Failed to fetch auth token.");
        }

        const data = await response.json();
        const expiryDate = new Date(data.expiry);

        return { token: data.token, expiry: expiryDate };
    }

    private set(token?: string, expiry?: Date): void {
        if (!token || !expiry) {
            return;
        }

        if (this.token === token) {
            return;
        }

        this.token = token;
        this.expiry = expiry;

        // Dispatch a custom event to notify other parts of the application
        const evt = new CustomEvent("@opti/auth/token", { detail: { token } });
        document.dispatchEvent(evt);

        this.notify();
    }
}
