import { CommonSettings } from "../autogenerated-types/CommonSettings";

let commonSettings: CommonSettings = {
    antiforgeryFormFieldName: "",
    antiforgeryHeaderName: "RequestVerificationToken",
    antiforgeryHeaderValue: "",
    shellModuleUrl: "/Optimizely/Shell",
    cmsModuleUrl: "/Optimizely/CMS",
    modules: [],
};

try {
    const resourcesContainer = document.getElementById("episerver-common-settings-container");
    const epiCommonSettings = resourcesContainer!.dataset.epiCommonSettings;

    commonSettings = JSON.parse(epiCommonSettings!);

    const antiforgeryFormField: HTMLInputElement = document.getElementsByName(
        commonSettings.antiforgeryFormFieldName ?? "__RequestVerificationToken",
    )[0] as HTMLInputElement;
    commonSettings.antiforgeryHeaderName = commonSettings.antiforgeryHeaderName ?? "RequestVerificationToken";
    commonSettings.antiforgeryHeaderValue = antiforgeryFormField?.value;
} catch {
    // logging
}

export { commonSettings };
